/*
 * Zippy's Crown Quest: recorded voice lines (see docs/VOICEOVER.md).
 *
 * Every line the caption or Zippy's speech bubble can show has a clip in assets/vo/ (Ogg Opus).
 * VO_LINES (js/vo_lines.js, generated by tools/vo_build.py) maps the exact text a line shows to its
 * clip and length, so a line is found by what it says, wherever the game says it. js/audio.js plays
 * the clips; a line without a clip, or a browser that can't play Ogg Opus (older Safari and iPads),
 * uses the device's own voice, as the game did before it had recordings.
 *
 *   CQVoice.lookup(text)  -> { id, secs, src } or null
 *   CQVoice.on()          -> true when recordings are in use
 *   CQVoice.element()     -> the one <audio> element every line plays on
 *   CQVoice.rate          -> playback speed: 1, or ?vospeed=2 (0.5–4) to check the lines quickly
 *   CQVoice.unlock()      -> call from a tap (Play): tablets only play sound that a tap started
 *   CQVoice.prefetch()    -> fetch every clip quietly, one at a time (when the game is on a server)
 *
 * ?vo=0 in the address turns the recordings off (the device voice reads every line).
 */
(function (win) {
  'use strict';

  var DIR = 'assets/vo/';
  var params = null;
  try { params = new win.URLSearchParams(win.location.search); } catch (e) { /* old browser */ }
  var off = !!params && params.get('vo') === '0';
  var rate = Math.max(0.5, Math.min(4, parseFloat(params && params.get('vospeed')) || 1));
  var el = null, unlocked = false, prefetching = false, opus = null;
  var blobs = {}; // clip id -> object URL of the prefetched file

  function lines() {
    return typeof VO_LINES !== 'undefined' ? VO_LINES : null; // eslint-disable-line no-undef
  }
  function canPlayOpus() {
    if (opus === null) {
      try { opus = typeof win.Audio === 'function' && new win.Audio().canPlayType('audio/ogg; codecs="opus"') !== ''; } catch (e) { opus = false; }
    }
    return opus;
  }
  function on() {
    return !off && !!lines() && canPlayOpus();
  }
  function lookup(text) {
    if (text === null || text === undefined || !on()) return null;
    var map = lines(), key = String(text);
    if (!Object.prototype.hasOwnProperty.call(map, key)) return null;
    var e = map[key];
    return { id: e[0], secs: e[1], src: blobs[e[0]] || DIR + e[0] + '.ogg' };
  }
  function element() {
    if (!el && typeof win.Audio === 'function') {
      el = new win.Audio();
      el.preload = 'auto';
    }
    return el;
  }
  function silentWav() { // a tiny silent WAV built in memory
    var n = 64, b = new Uint8Array(44 + n * 2), v = new DataView(b.buffer), s = '', i;
    function str(o, x) { for (var j = 0; j < x.length; j++) b[o + j] = x.charCodeAt(j); }
    str(0, 'RIFF'); v.setUint32(4, 36 + n * 2, true); str(8, 'WAVE'); str(12, 'fmt ');
    v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);
    v.setUint32(24, 8000, true); v.setUint32(28, 16000, true); v.setUint16(32, 2, true);
    v.setUint16(34, 16, true); str(36, 'data'); v.setUint32(40, n * 2, true);
    for (i = 0; i < b.length; i++) s += String.fromCharCode(b[i]);
    return 'data:audio/wav;base64,' + win.btoa(s);
  }
  // From the Play tap: play the element muted, then pause it, so later lines may play without a tap.
  function unlock() {
    if (unlocked || !on()) return;
    var a = element();
    if (!a) return;
    unlocked = true;
    var src = silentWav();
    function done() {
      if (a.src !== src) return; // a line has started meanwhile
      try { a.pause(); } catch (e) { /* ignore */ }
      a.muted = false;
    }
    try {
      a.muted = true;
      a.src = src;
      var p = a.play();
      if (p && p.then) p.then(done, done); else done();
    } catch (e) { a.muted = false; }
    prefetch();
  }
  // Fetch every clip quietly, one after another, so each is ready before it is needed. Only when the
  // game is served over http(s): opened straight from the folder, the files are already at hand.
  function prefetch() {
    var map = lines();
    if (prefetching || !on() || !/^https?:$/.test(win.location.protocol) || typeof win.fetch !== 'function' || !win.URL || !win.URL.createObjectURL) return;
    prefetching = true;
    var ids = [], k;
    for (k in map) if (Object.prototype.hasOwnProperty.call(map, k) && ids.indexOf(map[k][0]) < 0) ids.push(map[k][0]);
    ids.sort(); // vo001, vo002… is the order a child first hears them
    var i = 0;
    (function next() {
      if (i >= ids.length) return;
      var id = ids[i++];
      win.fetch(DIR + id + '.ogg')
        .then(function (r) { return r.ok ? r.blob() : null; })
        .then(function (b) { if (b && b.size) blobs[id] = win.URL.createObjectURL(b); }, function () { /* played from the file instead */ })
        .then(next, next);
    })();
  }

  win.CQVoice = {
    lookup: lookup,
    on: on,
    element: element,
    rate: rate,
    unlock: unlock,
    prefetch: prefetch
  };
})(window);
